mapper.update:
UPDATE tc_eqp_param_version
   SET version_description = #{e.versionDescription},
       updated_by          = COALESCE(#{e.updatedBy}, 'SYSTEM'),
       updated_at          = CURRENT_TIMESTAMP
 WHERE eqp_key = #{e.eqpKey}
   AND param_version = #{e.paramVersion}

mapper.select:
SELECT 
  FROM tc_eqp_param_version
 WHERE eqp_key = #{eqpKey}
   AND param_version = #{paramVersion}

SELECT 
  FROM tc_eqp_param_version
 WHERE eqp_key = #{eqpKey}
 ORDER BY eqp_param_version_key ASC

    LIMIT #{limit} OFFSET #{offset}
